theorem ProbabilityTheory.extracted_1.{u_4, u_2} {S : Type u_2} {U : Type u_4} [inst : MeasurableSpace S]
  [inst_1 : MeasurableSpace U] [inst_2 : MeasurableSingletonClass S] [inst_3 : MeasurableSingletonClass U]
  {μ : Measure (S × U)} [inst_4 : FiniteSupport μ] [inst_5 : IsZeroOrProbabilityMeasure μ] (hμ : IsProbabilityMeasure μ)
  (this_1 : IsProbabilityMeasure (Measure.map Prod.fst μ)) (this : IsProbabilityMeasure (Measure.map Prod.snd μ)) :
  let E := μ.support;
  μ (↑μ.support)ᶜ = 0 →
    let E1 := Finset.image Prod.fst E;
    let E2 := Finset.image Prod.snd E;
    μ (↑(E1 ×ˢ E2))ᶜ = 0 := sorry

theorem ProbabilityTheory.extracted_1.{u_4, u_2} {S : Type u_2} {U : Type u_4} [inst : MeasurableSpace S]
  [inst_1 : MeasurableSpace U] [inst_2 : MeasurableSingletonClass S] [inst_3 : MeasurableSingletonClass U]
  {μ : Measure (S × U)} [inst_4 : FiniteSupport μ] [inst_5 : IsZeroOrProbabilityMeasure μ] (hμ : IsProbabilityMeasure μ)
  (this_1 : IsProbabilityMeasure (Measure.map Prod.fst μ)) (this : IsProbabilityMeasure (Measure.map Prod.snd μ)) :
  let E := μ.support;
  μ (↑μ.support)ᶜ = 0 →
    let E1 := Finset.image Prod.fst E;
    let E2 := Finset.image Prod.snd E;
    μ (↑(E1 ×ˢ E2))ᶜ = 0 → ∀ (s : S) (u : U), μ {(s, u)} ≠ 0 → ∃ x, μ {(s, x)} ≠ 0 := sorry

theorem ProbabilityTheory.extracted_1.{u_3, u_2} {S : Type u_2} {T : Type u_3} [inst : MeasurableSpace S]
  [inst_1 : MeasurableSpace T] [inst_2 : MeasurableSingletonClass S] {μ : Measure S} {ν : Measure T}
  [inst_3 : FiniteSupport μ] [inst_4 : FiniteSupport ν] [inst_5 : IsProbabilityMeasure μ]
  [inst_6 : IsProbabilityMeasure ν] [inst_7 : MeasurableSingletonClass T] :
  let A := μ.support;
  μ (↑μ.support)ᶜ = 0 →
    let B := ν.support;
    ν (↑ν.support)ᶜ = 0 → (μ.prod ν) (↑(A ×ˢ B))ᶜ = 0 := sorry

theorem ProbabilityTheory.extracted_1.{u_3, u_2} {S : Type u_2} {T : Type u_3} [inst : MeasurableSpace S]
  [inst_1 : MeasurableSpace T] [inst_2 : MeasurableSingletonClass S] {μ : Measure S} {ν : Measure T}
  [inst_3 : FiniteSupport μ] [inst_4 : FiniteSupport ν] [inst_5 : IsProbabilityMeasure μ]
  [inst_6 : IsProbabilityMeasure ν] [inst_7 : MeasurableSingletonClass T] :
  let A := μ.support;
  μ (↑μ.support)ᶜ = 0 →
    let B := ν.support;
    ν (↑ν.support)ᶜ = 0 →
      (μ.prod ν) (↑(A ×ˢ B))ᶜ = 0 →
        Hm[μ] = ∑ p ∈ A ×ˢ B, (μ.real {p.1}).negMulLog * ν.real {p.2} → μ.real ↑A = μ.real univ := sorry

theorem ProbabilityTheory.extracted_1.{u_2} {S : Type u_2} [inst : MeasurableSpace S] {μ : Measure S}
  [inst_1 : MeasurableSingletonClass S] [inst_2 : Fintype S] [inst_3 : IsFiniteMeasure μ] [inst_4 : NeZero μ]
  (h : IsEmpty S) : Hm[μ] = log ↑(Fintype.card S) ↔ ∀ (s : S), μ {s} = μ univ / ↑(Fintype.card S) := sorry

theorem ProbabilityTheory.extracted_1.{u_2} {S : Type u_2} [inst : MeasurableSpace S] {μ : Measure S}
  [inst_1 : MeasurableSingletonClass S] [inst_2 : Fintype S] [inst_3 : IsFiniteMeasure μ] [inst_4 : NeZero μ]
  (h : Nonempty S) : μ univ * (↑(Fintype.card S))⁻¹ ≠ ⊤ := sorry

theorem ProbabilityTheory.extracted_1.{u_2} {S : Type u_2} [inst : MeasurableSpace S]
  [inst_1 : MeasurableSingletonClass S] [inst_2 : Fintype S] (μ : Measure S) [inst_3 : IsProbabilityMeasure μ]
  (h : Nonempty S) :
  let N := Fintype.card S;
  (↑N)⁻¹ ≠ 0 →
    let w := fun x => (↑N)⁻¹;
    (∀ s ∈ Finset.univ, 0 < w s) →
      ∑ s : S, w s = 1 →
        let p := fun s => μ.real {s};
        ∀ s ∈ Finset.univ, 0 ≤ p s := sorry

theorem ProbabilityTheory.extracted_1.{u_2} {S : Type u_2} [inst : MeasurableSpace S]
  [inst_1 : MeasurableSingletonClass S] [inst_2 : Fintype S] (μ : Measure S) [inst_3 : IsProbabilityMeasure μ]
  (h : Nonempty S) :
  let N := Fintype.card S;
  (↑N)⁻¹ ≠ 0 →
    let w := fun x => (↑N)⁻¹;
    (∀ s ∈ Finset.univ, 0 < w s) →
      ∑ s : S, w s = 1 →
        let p := fun s => μ.real {s};
        (∀ s ∈ Finset.univ, 0 ≤ p s) → (↑N)⁻¹ * log ↑N = (∑ i : S, w i • p i).negMulLog := sorry

theorem ProbabilityTheory.extracted_1.{u_2} {S : Type u_2} [inst : MeasurableSpace S] {μ : Measure S} {A : Finset S}
  (hA : μ (↑A)ᶜ = 0) [inst_1 : IsZeroOrProbabilityMeasure μ] (hμ : IsProbabilityMeasure μ) :
  ∑ s ∈ A, (((μ univ)⁻¹ • μ) {s}).toReal.negMulLog = ∑ s ∈ A, (μ {s}).toReal.negMulLog := sorry

theorem ProbabilityTheory.extracted_1.{u_5, u_2} {S : Type u_2} [inst : MeasurableSpace S]
  [inst_1 : MeasurableSingletonClass S] (μ : Measure S) [inst_2 : FiniteSupport μ] {β : Type u_5}
  [inst_3 : NormedAddCommGroup β] [inst_4 : IsFiniteMeasure μ] [inst_5 : Countable S] {f : S → β} :
  let A := μ.support;
  μ (↑A)ᶜ = 0 → A = ∅ → Integrable f μ := sorry

theorem ProbabilityTheory.extracted_1.{u_5, u_2} {S : Type u_2} [inst : MeasurableSpace S]
  [inst_1 : MeasurableSingletonClass S] (μ : Measure S) [inst_2 : FiniteSupport μ] {β : Type u_5}
  [inst_3 : NormedAddCommGroup β] [inst_4 : IsFiniteMeasure μ] [inst_5 : Countable S] {f : S → β} :
  let A := μ.support;
  μ (↑A)ᶜ = 0 → ¬A = ∅ → Integrable f μ := sorry

theorem ProbabilityTheory.extracted_1.{u_5, u_2} {S : Type u_2} [inst : MeasurableSpace S]
  [inst_1 : MeasurableSingletonClass S] (μ : Measure S) [inst_2 : FiniteSupport μ] {β : Type u_5}
  [inst_3 : NormedAddCommGroup β] [inst_4 : IsFiniteMeasure μ] [inst_5 : Countable S] {f : S → β} :
  let A := μ.support;
  μ (↑A)ᶜ = 0 → ¬A = ∅ → (∃ s₀, s₀ ∈ A) → Integrable f μ := sorry

theorem ProbabilityTheory.extracted_1.{u_5, u_2} {S : Type u_2} [inst : MeasurableSpace S]
  [inst_1 : MeasurableSingletonClass S] (μ : Measure S) [inst_2 : FiniteSupport μ] {β : Type u_5}
  [inst_3 : IsFiniteMeasure μ] [inst_4 : Countable S] {f : S → β} :
  let A := μ.support;
  μ (↑A)ᶜ = 0 →
    ¬A = ∅ →
      ∀ (s₀ : S) (hs₀ : s₀ ∈ A),
        let f' := fun a => f ↑a;
        let g := fun s => if h : s ∈ A then ⟨s, h⟩ else ⟨s₀, hs₀⟩;
        f' ∘ g =ᶠ[ae μ] f := sorry

theorem ProbabilityTheory.extracted_1.{u_5, u_2} {S : Type u_2} [inst : MeasurableSpace S]
  [inst_1 : MeasurableSingletonClass S] (μ : Measure S) [inst_2 : FiniteSupport μ] {β : Type u_5}
  [inst_3 : NormedAddCommGroup β] [inst_4 : IsFiniteMeasure μ] [inst_5 : Countable S] {f : S → β} :
  let A := μ.support;
  μ (↑A)ᶜ = 0 →
    ¬A = ∅ →
      ∀ (s₀ : S) (hs₀ : s₀ ∈ A),
        let f' := fun a => f ↑a;
        let g := fun s => if h : s ∈ A then ⟨s, h⟩ else ⟨s₀, hs₀⟩;
        f' ∘ g =ᶠ[ae μ] f → Integrable f μ := sorry
